function renderStatuses(){let chips=[];if(state.block)chips.push(`<span class="status-chip">◈ Block <strong>${state.block}</strong></span>`);if(state.strength)chips.push(`<span class="status-chip">✦ Strength <strong>${state.strength}</strong></span>`);if(state.chill)chips.push(`<span class="status-chip">❄ Chill <strong>${state.chill}</strong></span>`);$('statusChips').innerHTML=chips.join('')}
function flashText(text,color='#ff8177'){let f=document.createElement('span');f.className='float';f.textContent=text;f.style.color=color;f.style.left=`${32+rand(35)}%`;f.style.top='43%';$('floats').appendChild(f);setTimeout(()=>f.remove(),950)}
function damageEnemy(amount,opts={}){if(amount<=0)return;let dmg=amount;if(state.hero==='ichigo'&&state.firstAttack){dmg+=3;state.firstAttack=false}if(state.hero==='uryu'&&(state.played+1)%3===0)dmg+=5;if(state.hero==='renji'&&state.enemyBlock>0)dmg+=2;if(state.firstFight){dmg+=2}let absorbed=Math.min(state.enemyBlock,dmg);state.enemyBlock-=absorbed;dmg-=absorbed;state.enemyHp=Math.max(0,state.enemyHp-dmg);$('enemyWrap').classList.remove('hit');void $('enemyWrap').offsetWidth;$('enemyWrap').classList.add('hit');flashText(`-${dmg}`, '#ff8177');addLog(`<strong>${HEROES[state.hero].name.split(' ')[0]}</strong> deals ${dmg} damage${absorbed?` (${absorbed} blocked)`:''}.`);if(state.enemyHp<=0)winBattle();render()}
function playCard(index){if(!state.playerTurn)return;let id=state.hand[index];if(!id)return;let meta=CARD_META[id]||CARD_META.slash,h=HEROES[state.hero],details=h.cards[id]||[meta[0],'',meta[3],meta[4]],cost=meta[1];if(state.hero==='rukia'&&details[2]==='SKILL'&&state.firstSkill)cost=0;if(state.energy<cost)return;state.energy-=cost;state.played++;if(details[2]==='SKILL'&&state.hero==='rukia')state.firstSkill=false;state.hand.splice(index,1);state.discard.push(id);let log=details[0];if(id==='slash'||id==='icecut'||id==='arrow'||id==='twin'){damageEnemy(meta[2]);if(id==='icecut'){state.chill=Math.min(3,state.chill+1);addLog('The Hollow is chilled.')}}else if(id==='getsuga'||id==='tsukishiro'||id==='howl'){damageEnemy(meta[2]);if(id==='getsuga')state.block+=2;if(id==='tsukishiro'){state.chill=Math.min(3,state.chill+2);addLog('Tsukishiro slows the Hollow.') }}else if(id==='licht'){for(let i=0;i<3;i++){if(state.enemyHp>0)damageEnemy(meta[2])}}else if(id==='precision'){damageEnemy(meta[2]+(state.chill?4:0))}else if(id==='fang'){damageEnemy(meta[2]);state.bleed+=2;addLog('Bleed applied: 2.') }else if(id==='guard'){state.block+=state.hero==='rukia'?6:state.hero==='renji'?6:5;flashText(`+${state.hero==='rukia'||state.hero==='renji'?6:5} BLOCK`,'#83cfc5')}else if(id==='flash'){state.block+=4;drawCard();flashText('+4 BLOCK','#83cfc5')}else if(id==='focus'){state.strength+=2;state.hp=Math.max(1,state.hp-2);flashText('+2 STRENGTH','#c9a7df');addLog('The Hollow mask surges; 2 HP lost.')}else if(id==='snow'){state.block+=4;drawCard();state.chill=Math.min(3,state.chill+1);flashText('+4 BLOCK','#83cfc5')}else if(id==='precision'){damageEnemy(meta[2])}else if(id==='howl'){damageEnemy(meta[2])}else if(id==='fang'){damageEnemy(meta[2]);state.bleed+=2}if(state.strength&&details[2]==='ATTACK'){}addLog(`<strong>${esc(log)}</strong> played.`);if(state.enemyHp>0&&state.hand.length===0){}render()}
function endTurn(){if(!state.playerTurn||state.enemyHp<=0)return;state.playerTurn=false;state.discard.push(...state.hand);state.hand=[];if(state.bleed){state.enemyHp=Math.max(0,state.enemyHp-state.bleed);flashText(`BLEED -${state.bleed}`,'#ed7774');addLog(`Bleed deals ${state.bleed} damage.`);if(state.enemyHp<=0){winBattle();render();return}}if(state.enemyHp>0){let dmg=state.enemyDamage;if(state.chill){dmg=Math.max(1,dmg-state.chill*2);state.chill=Math.max(0,state.chill-1)}let blocked=Math.min(state.block,dmg),taken=dmg-blocked;state.block-=blocked;state.hp=Math.max(0,state.hp-taken);if(taken)flashText(`-${taken} HP`,'#ff8177');addLog(`<strong>${state.enemyName}</strong> strikes for ${dmg}${blocked?`, ${blocked} blocked`:''}.`);if(state.hp<=0){render();showGameOver(false);return}}state.turn++;state.enemyDamage=Math.min(22,9+Math.floor(state.floor/2)+rand(4));startTurn();addLog(`Turn ${state.turn} begins. Draw 5.`)}
function winBattle(){if(state.phase!=='battle')return;state.phase='reward';state.playerTurn=false;state.souls+=12;state.hp=Math.min(state.maxHp,state.hp+3);state.routeDone=Math.min(4,state.floor-1);addLog('Hollow purified. +12 Soul fragments.');setTimeout(showReward,350)}
function showReward(){let h=HEROES[state.hero],pool=[...new Set(h.deck)].filter(id=>!state.deck.includes(id)||Math.random()>.35);if(pool.length<3)pool=[...new Set(h.deck)];let opts=shuffle(pool).slice(0,3);let html=`<div class="modal-kicker">HOLLOW PURIFIED · +12 SOUL FRAGMENTS</div><h2>Choose your next technique</h2><p>A fragment of power remains. Add one card to your deck, or leave the spirit behind.</p><div class="choice-list">${opts.map(id=>{let m=CARD_META[id],d=h.cards[id];return `<button class="reward-choice" data-reward="${id}"><span class="mini-type">${m[3]} · COST ${m[1]}</span><b>${esc(d[0])}</b><span>${esc(d[1])}</span></button>`}).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="skipReward">Skip reward</button></div>`;openModal(html);document.querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{state.deck.push(b.dataset.reward);closeModal();showPathChoice()});$('skipReward').onclick=()=>{closeModal();showPathChoice()}}
function showPathChoice(){if(state.floor>=5){showGameOver(true);return}let isElite=state.floor===3;openModal(`<div class="modal-kicker">THE HOLLOW MARCH · FLOOR ${String(state.floor+1).padStart(2,'0')}</div><h2>Choose your path</h2><p>The reishi currents split ahead. Decide how to prepare for the next encounter.</p><div class="choice-list"><button class="reward-choice" data-path="rest"><span class="mini-type">CAMPFIRE · SAFE</span><b>Seireitei Refuge</b><span>Recover 14 vitality before moving on.</span></button><button class="reward-choice" data-path="shrine"><span class="mini-type">SOUL WELL · RISK / REWARD</span><b>Spirit Shrine</b><span>Gain 8 vitality and 15 Soul fragments.</span></button><button class="reward-choice" data-path="march"><span class="mini-type">CONTINUE · ${isElite?'ELITE':'BATTLE'}</span><b>Press onward</b><span>Keep your wounds. Face the next Hollow.</span></button></div>`);document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{if(b.dataset.path==='rest'){state.hp=Math.min(state.maxHp,state.hp+14);addLog('Rested at Seireitei Refuge. +14 HP.')}if(b.dataset.path==='shrine'){state.hp=Math.min(state.maxHp,state.hp+8);state.souls+=15;addLog('Spirit Shrine grants +8 HP and +15 fragments.')}closeModal();nextEncounter()})}
function nextEncounter(){state.floor++;state.routeDone=state.floor-1;state.phase='battle';state.enemyType=state.floor===3?'elite':state.floor===5?'boss':'battle';state.enemyName=state.floor===5?' menos grande':state.floor===3?'The Gōrō Hollow':(['The Lost Soul','Ashen Hollow','The Devouring Hollow'][rand(3)]);state.enemyMax=state.floor===5?92:state.floor===3?62:38+state.floor*4;state.enemyHp=state.enemyMax;state.enemyDamage=state.floor===5?18:state.floor===3?14:10+Math.floor(state.floor/2);state.enemyBlock=0;state.bleed=0;state.chill=0;state.firstFight=true;state.firstAttack=true;state.discard.push(...state.hand);state.hand=[];state.draw=shuffle([...state.deck]);state.discard=[];state.turn=1;state.block=0;state.phase='battle';state.playerTurn=false;startTurn(true);addLog(`${state.enemyName} emerges from the shadows.`);render()}
function showGameOver(won){state.phase=won?'victory':'defeat';let content=won?`<div class="modal-kicker">SOUL SOCIETY · RUN COMPLETE</div><h2>The March is over.</h2><p>You broke the Hollow tide and carried ${state.souls} Soul fragments from the battlefield. The souls you saved will remember.</p><div class="modal-actions"><button class="primary-btn" id="restartRun">Begin a new run</button></div>`:`<div class="modal-kicker">YOUR SOUL FADES</div><h2>Even a Soul Reaper falls.</h2><p>You reached floor ${state.floor} and gathered ${state.souls} Soul fragments. The path will be here when you are ready.</p><div class="modal-actions"><button class="primary-btn" id="restartRun">Rise again</button></div>`;openModal(content);$('restartRun').onclick=()=>{state.run++;init();closeModal()}}
function openModal(html){$('modal').innerHTML=html;$('overlay').classList.add('show')}
function closeModal(){$('overlay').classList.remove('show')}
function showMenu(){let chosen=state.hero;openModal(`<div class="modal-kicker">SOUL REAPER · NEW RUN</div><h2>Choose your Soul Reaper</h2><p>Four paths into the Hollow March. Each fighter carries a unique deck, signature techniques, and combat instinct.</p><div class="hero-select">${Object.entries(HEROES).map(([id,h])=>`<button class="hero-option ${id===chosen?'selected':''}" data-hero="${id}"><div class="pick-avatar avatar">${heroArt(id)}</div><b>${h.name.split(' ')[0]}</b><small>${h.title}</small></button>`).join('')}</div><div class="modal-actions"><button class="secondary-btn" id="closeMenu">Return to battle</button><button class="primary-btn" id="startRun">Start new run</button></div><p style="margin:16px 0 0;font-size:10px">Play cards by tapping them. Attacks strike the Hollow; skills protect you. End your turn to resolve its intent.</p>`);document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{chosen=b.dataset.hero;document.querySelectorAll('[data-hero]').forEach(x=>x.classList.toggle('selected',x.dataset.hero===chosen))});$('closeMenu').onclick=closeModal;$('startRun').onclick=()=>{state.hero=chosen;state.run++;init();closeModal()}}
$('hand').addEventListener('click',e=>{let b=e.target.closest('[data-i]');if(b)playCard(Number(b.dataset.i))});$('endTurn').onclick=endTurn;$('endTurnMobile').onclick=endTurn;$('menuBtn').onclick=showMenu;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&$('overlay').classList.contains('show')===false)endTurn()});
$('enemyArt').innerHTML=heroArt('ichigo',true);init();
</script>
</body>
</html>

